// msg.topic = OSC address, msg.payload = arg(s), msg.ip/msg.port = sender
if (msg.topic === 'bundle') { return null; } // ignore bundles for now
const parts = msg.topic.split('/').filter(Boolean);
if (parts.length < 2) { node.warn('bad address: ' + msg.topic); return null; }

const device = parts[0];
const param  = parts.slice(1).join('/');
const value  = Array.isArray(msg.payload) && msg.payload.length === 1 ? msg.payload[0] : msg.payload;

const devices = flow.get('devices') || {};
const d = devices[device] || { params: {} };
d.ip = msg.ip;
d.lastSeen = Date.now();
d.params[param] = value;
devices[device] = d;
flow.set('devices', devices);

return { device, param, value, ip: msg.ip, topic: msg.topic };

// Minimal routing: source param -> target device/param. Edit freely.
const routes = {
  'cassette/speed': [ { device: 'turntable', param: 'speed', scale: 1.0 } ],
  // 'tv/disk_rpm':   [ { device: 'cassette',  param: 'speed', scale: 1.0 } ],
};

const key = msg.device + '/' + msg.param;
const targets = routes[key];
if (!targets) { return null; }

const devices = flow.get('devices') || {};
const out = [];
for (const t of targets) {
  const dest = devices[t.device];
  if (!dest || !dest.ip) { node.warn('target not online: ' + t.device); continue; }
  let v = Number(msg.value) * (t.scale || 1);
  v = Math.max(0, Math.min(1, v));
  out.push({
    topic: '/' + t.device + '/set/' + t.param,
    payload: { type: 'f', value: v },
    ip: dest.ip,
    port: 9001
  });
}
return [out];

const dev = msg.topic.split('/').filter(Boolean)[0];
const d = (flow.get('devices') || {})[dev];
if (!d || !d.ip) { node.warn('device not online: ' + dev); return null; }
msg.ip = d.ip; msg.port = 9001;
return msg;

const devices = flow.get('devices') || {};
const now = Date.now();
const report = {};
for (const [name, d] of Object.entries(devices)) {
  report[name] = { online: (now - d.lastSeen) < 3000, ip: d.ip, ageMs: now - d.lastSeen, params: d.params };
}
return { payload: report };
